import 'package:path/path.dart' as p;
import 'package:yaml/yaml.dart';

/// Settings of the search, read from the `appcraft_unused_assets` section of
/// `pubspec.yaml`.
final class UnusedAssetsConfig {
  /// Creates a configuration, falling back to the defaults.
  const UnusedAssetsConfig({
    this.generated = defaultGenerated,
    this.scan = defaultScan,
    this.ignore = const <String>[],
    this.entryPoints,
  });

  /// Reads the configuration from the content of a `pubspec.yaml`.
  ///
  /// The path of the generated file falls back to the `output` flutter_gen is
  /// configured with, so a project that configured flutter_gen needs no
  /// configuration of its own. Like flutter_gen itself, the options of its
  /// builder in [build] — the content of a `build.yaml` — take precedence over
  /// the `flutter_gen` section of the pubspec.
  factory UnusedAssetsConfig.fromPubspec(String pubspec, {String? build}) {
    final section = _sectionOf(pubspec, 'appcraft_unused_assets');
    final entryPoints = _stringList(section?['entry_points']);

    return UnusedAssetsConfig(
      generated: section?['generated'] as String? ??
          _generatedOfFlutterGen(pubspec, build),
      scan: _stringList(section?['scan']) ?? defaultScan,
      ignore: _stringList(section?['ignore']) ?? const <String>[],
      entryPoints: entryPoints == null || entryPoints.isEmpty
          ? null
          : entryPoints,
    );
  }

  /// File generated by flutter_gen, relative to the project root.
  final String generated;

  /// Directories scanned for usages, relative to the project root.
  final List<String> scan;

  /// Asset paths left out of the report.
  ///
  /// An entry matches an asset whose path equals it or lies inside it, so a
  /// directory covers everything under it.
  final List<String> ignore;

  /// Files under `lib` the app starts from, relative to the project root.
  ///
  /// A file under `lib` that none of them reaches through its imports, exports
  /// and parts is dead code, and what it refers to does not count. Files
  /// outside `lib`, such as the tests, are always read. When `null`, the files
  /// under `lib` that declare a top-level `main` are taken.
  final List<String>? entryPoints;

  /// Default value of [generated], used when flutter_gen is not configured.
  static const String defaultGenerated = 'lib/gen/assets.gen.dart';

  /// Default value of [scan].
  static const List<String> defaultScan = <String>[
    'lib',
    'test',
  ];

  /// Whether [assetPath] is covered by [ignore].
  bool ignores(String assetPath) {
    final asset = p.posix.normalize(assetPath.replaceAll(r'\', '/'));

    return ignore.any((entry) {
      final ignored = p.posix.normalize(entry.replaceAll(r'\', '/'));
      return asset == ignored || p.posix.isWithin(ignored, asset);
    });
  }

  static String _generatedOfFlutterGen(String pubspec, String? build) {
    final output = _outputOfBuild(build, _packageNameOf(pubspec)) ??
        _sectionOf(pubspec, 'flutter_gen')?['output'];
    if (output is! String) return defaultGenerated;

    return p.posix.join(
      output.replaceAll(r'\', '/'),
      'assets.gen.dart',
    );
  }

  /// The `output` a `build.yaml` gives the flutter_gen builder.
  ///
  /// Options are taken in the order build_runner applies them in its default
  /// mode: the global options over the options of the default target, and
  /// `dev_options` over `options` within each.
  static Object? _outputOfBuild(String? build, String? packageName) {
    if (build == null) return null;

    final document = loadYaml(build);
    if (document is! YamlMap) return null;

    final target = _entryOf(document['targets'], <String>[
      r'$default',
      r':$default',
      r'$default:$default',
      if (packageName != null) ...[packageName, '$packageName:$packageName'],
    ]);
    final builder = _entryOf(target?['builders'], _builderKeys);
    final global = _entryOf(document['global_options'], _builderKeys);

    for (final options in [
      global?['dev_options'],
      global?['options'],
      builder?['dev_options'],
      builder?['options'],
    ]) {
      if (options case {'output': final Object output}) return output;
    }

    return null;
  }

  /// Keys the flutter_gen builder is configured under: every spelling
  /// build_runner normalizes to it, and `flutter_gen`, read by the `fluttergen`
  /// command.
  static const List<String> _builderKeys = <String>[
    'flutter_gen_runner',
    'flutter_gen_runner:flutter_gen_runner',
    'flutter_gen_runner|flutter_gen_runner',
    'flutter_gen',
  ];

  /// The first map found in [map] under one of [keys].
  static YamlMap? _entryOf(Object? map, List<String> keys) {
    if (map is! YamlMap) return null;

    for (final key in keys) {
      if (map[key] case final YamlMap entry) return entry;
    }

    return null;
  }

  static String? _packageNameOf(String pubspec) =>
      switch (loadYaml(pubspec)) {
        {'name': final String name} => name,
        _ => null,
      };

  static YamlMap? _sectionOf(String pubspec, String key) {
    final document = loadYaml(pubspec);
    if (document is! YamlMap) return null;

    final section = document[key];
    return section is YamlMap ? section : null;
  }

  static List<String>? _stringList(Object? value) {
    if (value is! YamlList) return null;

    return <String>[
      for (final entry in value)
        if (entry is String) entry,
    ];
  }
}
